import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { Plane } from '../Entity/Plane';
import type { Turret } from '../Entity/Turret';

export class TurretAimSystem implements System {

    onTick(world: World, _dt: number): void {
        for (const turret of world.query<Turret>('turret')) {
            if (!turret.alive || turret.hp <= 0) continue;
            this._tickAim(world, turret, _dt);
        }
    }

    private _tickAim(world: World, turret: Turret, dt: number): void {
        const c = turret.config;
        switch (c.aimMode) {
            case 'fixed':
                turret.aimAngle = c.baseAngle;
                break;
            case 'target':
                this._aimAtPlayer(world, turret, dt);
                break;
            case 'spin':
                turret.aimAngle = (turret.aimAngle + c.aimSpeed * dt) % 360;
                break;
            case 'oscillate':
                turret.oscPhase += (c.aimSpeed * Math.PI / 180) * dt;
                turret.aimAngle = c.baseAngle + Math.sin(turret.oscPhase) * c.oscRange;
                break;
        }
    }

    private _aimAtPlayer(world: World, turret: Turret, dt: number): void {
        const player = this._findPlayer(world);
        if (!player) return;

        const c = turret.config;
        const targetAngle = Math.atan2(player.y - turret.y, player.x - turret.x) * 180 / Math.PI;

        let diff = targetAngle - turret.aimAngle;
        diff = ((diff + 180) % 360 + 360) % 360 - 180;

        const maxStep = c.aimSpeed * dt;
        if (Math.abs(diff) <= maxStep) {
            turret.aimAngle = targetAngle;
        } else {
            turret.aimAngle += Math.sign(diff) * maxStep;
        }
    }

    private _findPlayer(world: World): Plane | null {
        for (const p of world.query<Plane>('player')) return p;
        return null;
    }
}